<script setup lang="ts">
/**
 * A Dialog preset for confirming an action (`design/components/confirm-dialog.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/confirm-dialog.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, getCurrentInstance, onBeforeUnmount, onMounted, provide, ref, watch } from 'vue'

import { agentMember } from '@polymorph/vue'
import Button from '../controls/Button.vue'
import Dialog from './Dialog.vue'
import FormField from '../controls/FormField.vue'
import Input from '../controls/Input.vue'

export type ConfirmTone = NonNullable<ConfirmDialogProps['tone']>

export interface ConfirmDialogProps {
  cancelLabel?: string
  closeLabel?: string
  /**
   * The action's verb; it has no default, so the caller must name the action.
   */
  confirmLabel: string
  /**
   * A typed confirmation: the phrase the person types before the confirm enables, such as the
   * name of the project being deleted. The body draws its field, and focus starts there in both
   * tones.
   */
  confirmWith?: string
  /**
   * The phrase field's error while its text cannot become the phrase, `The text does not match`
   * by default.
   */
  confirmWithError?: string
  /**
   * The phrase field's label, `Type {confirmWith} to confirm` by default. Localized hosts pass
   * their own, with the phrase in it.
   */
  confirmWithLabel?: string
  /**
   * Required, because a confirm must say what is at stake.
   */
  description: string
  open?: boolean
  /**
   * Dialog's `presentation`, passed through (the sheet presentation,
   * `design/components/README.md`). A confirm is the content-light dialog this option is for.
   * `'sheet'` keeps the sm card above `30rem` and uses a bottom sheet below it. Footer order,
   * cancel-first initial focus and the pending lock are the same in both forms.
   */
  presentation?: 'auto' | 'sheet'
  title: string
  /**
   * `accent` for consequential but safe actions; the `danger` default is for destructive ones.
   */
  tone?: 'accent' | 'danger'
}

defineOptions({ name: 'ConfirmDialog', inheritAttrs: false })

const props = withDefaults(defineProps<ConfirmDialogProps>(), {
  cancelLabel: 'Cancel',
  closeLabel: 'Close',
  confirmWithError: 'The text does not match',
  open: undefined,
  presentation: 'auto',
  tone: 'danger',
})
const emit = defineEmits<{ confirm: []; openChange: [open: boolean] }>()
defineSlots<{ trigger?: (props: Record<string, never>) => unknown }>()
provide('polymorph:identity', 'confirm-dialog')
const borrowed: { element?: () => Element | null | undefined } = {}
provide('polymorph:borrowed', borrowed)
// Calls the caller's handlers for an event and returns what they return, which `emit` drops.
const instance = getCurrentInstance()
const invoke = (event: string, ...args: unknown[]): unknown => {
  const bound: unknown =
    instance?.vnode.props?.[`on${event.charAt(0).toUpperCase()}${event.slice(1)}`]
  const results = (Array.isArray(bound) ? bound : [bound]).flatMap((handler: unknown) =>
    typeof handler === 'function' ? [handler(...args)] : [],
  )
  return results.length > 1 ? Promise.all(results) : results[0]
}
const mirror = ref(false)
const pending = ref(false)
const typed = ref('')
const current = computed(() => props.open ?? mirror.value)
const phrase = computed(() =>
  props.confirmWith === undefined ? undefined : props.confirmWith.trim().toLowerCase(),
)
const entered = computed(() => typed.value.trim().toLowerCase())
const holds = computed(() => phrase.value === undefined || entered.value === phrase.value)
const wrong = computed(
  () =>
    phrase.value !== undefined && entered.value !== '' && !phrase.value.startsWith(entered.value),
)
const setOpen = computed(() => (next: boolean) => {
  mirror.value = next
  emit('openChange', next)
})
const confirm = computed(() => async () => {
  const result = invoke('confirm')
  if (!(result instanceof Promise)) {
    setOpen.value(false)
    return
  }
  pending.value = true
  try {
    await result
    setOpen.value(false)
  } finally {
    pending.value = false
  }
})
const effect1 = () => {
  current.value && (typed.value = '')
}
watch(() => current.value, effect1, { flush: 'post' })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'ConfirmDialog',
    element: () => borrowed.element?.(),
    state: () => ({ open: current.value, pending: pending.value }),
    actions: {
      cancel: () =>
        (() => {
          if (pending.value)
            throw new Error('The confirmed action is running; it cannot be cancelled.')
          setOpen.value(false)
        })(),
    },
    withholds: () => borrowed.element?.(),
  })
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
</script>

<template>
  <Dialog
    :closeLabel="closeLabel"
    size="sm"
    :title="title"
    :description="description"
    :open="current"
    :presentation="presentation"
    :dismissible="!pending"
    :alert="tone === 'danger'"
    :initialFocus="tone === 'danger' && confirmWith === undefined ? 'dismiss' : 'primary'"
    @openChange="setOpen($event)"
  >
    <template #trigger>
      <slot name="trigger" />
    </template>
    <template v-if="confirmWith !== undefined" #default>
      <FormField
        :label="confirmWithLabel ?? `Type ${confirmWith} to confirm`"
        :error="wrong ? confirmWithError : undefined"
      >
        <Input
          :value="typed"
          autoComplete="off"
          :exact="true"
          :disabled="pending"
          @change="typed = $event"
        />
      </FormField>
    </template>
    <template #footer>
      <Button
        variant="outline"
        tone="neutral"
        :label="cancelLabel"
        :disabled="pending"
        @click="setOpen(false)"
      />
      <Button
        variant="solid"
        :tone="tone"
        :label="confirmLabel"
        :loading="pending"
        :disabled="!holds"
        @click="confirm()"
      />
    </template>
  </Dialog>
</template>
